// AccountingNote.jsx
// Self-contained revision note as a component. Import and render <AccountingNote />.
// The full standalone page (content + PYQ modal + quiz) lives in the string below and
// runs inside an iframe, so its own <script>/<style> execute in isolation and cannot
// collide with your app. The bundler sees only a JS string — never a <script> to extract.

const html =
  '<!DOCTYPE html>\n<html lang="en" data-theme="light">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Accounting — Complete Revision Note · UPSC APFC 2026</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Spectral:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400;1,500&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet">\n<style>\n  :root{\n    --paper:#f8faf7;\n    --paper-2:#eef2ec;\n    --card:#ffffff;\n    --ink:#12241c;\n    --ink-soft:#3c4f45;\n    --ink-faint:#6b7d73;\n    --green:#0f5137;\n    --green-bright:#127a52;\n    --green-line:#c3d6cb;\n    --red:#9e2b25;\n    --red-soft:#c85a52;\n    --gold:#9a7420;\n    --gold-soft:#f3ead0;\n    --rule:#d5e0d8;\n    --rule-strong:#a9bcb0;\n    --shadow:0 1px 0 rgba(18,36,28,.04), 0 8px 30px -18px rgba(18,36,28,.35);\n    --maxw:74ch;\n  }\n  :root:not([data-theme="light"]){\n    @media (prefers-color-scheme: dark){\n      --paper:#0f1613; --paper-2:#141d19; --card:#161f1b; --ink:#e7eee9;\n      --ink-soft:#b3c1b9; --ink-faint:#83958b; --green:#5cc79a; --green-bright:#6fd6a9;\n      --green-line:#2b4438; --red:#e8887f; --red-soft:#d97169; --gold:#d9bd77;\n      --gold-soft:#2a2416; --rule:#26362e; --rule-strong:#3a5044;\n      --shadow:0 1px 0 rgba(0,0,0,.3), 0 10px 30px -18px rgba(0,0,0,.7);\n    }\n  }\n  :root[data-theme="dark"]{\n    --paper:#0f1613; --paper-2:#141d19; --card:#161f1b; --ink:#e7eee9;\n    --ink-soft:#b3c1b9; --ink-faint:#83958b; --green:#5cc79a; --green-bright:#6fd6a9;\n    --green-line:#2b4438; --red:#e8887f; --red-soft:#d97169; --gold:#d9bd77;\n    --gold-soft:#2a2416; --rule:#26362e; --rule-strong:#3a5044;\n    --shadow:0 1px 0 rgba(0,0,0,.3), 0 10px 30px -18px rgba(0,0,0,.7);\n  }\n\n  *{box-sizing:border-box}\n  html{scroll-behavior:smooth}\n  @media (prefers-reduced-motion: reduce){html{scroll-behavior:auto}}\n  body{\n    margin:0; background:var(--paper); color:var(--ink);\n    font-family:"Inter",system-ui,-apple-system,sans-serif;\n    font-size:17px; line-height:1.7; letter-spacing:-.005em;\n    -webkit-font-smoothing:antialiased;\n  }\n  body::before{\n    /* faint ledger ruling behind the page */\n    content:""; position:fixed; inset:0; pointer-events:none; z-index:0;\n    background-image:linear-gradient(var(--rule) 1px, transparent 1px);\n    background-size:100% 2.55em; opacity:.35;\n  }\n\n  /* progress bar */\n  #scrollbar{position:fixed; top:0; left:0; height:3px; width:0%; z-index:50;\n    background:linear-gradient(90deg,var(--green),var(--green-bright)); }\n\n  /* layout */\n  .wrap{position:relative; z-index:1; max-width:1180px; margin:0 auto; padding:0 20px;\n    display:grid; grid-template-columns:260px minmax(0,1fr); gap:44px;}\n  @media(max-width:940px){.wrap{grid-template-columns:1fr; gap:0}}\n\n  /* sidebar */\n  aside{position:sticky; top:0; align-self:start; height:100vh; overflow-y:auto;\n    padding:26px 4px 40px; border-right:1px solid var(--rule);}\n  aside::-webkit-scrollbar{width:6px}\n  aside::-webkit-scrollbar-thumb{background:var(--rule-strong); border-radius:3px}\n  @media(max-width:940px){\n    aside{position:static; height:auto; border-right:none; border-bottom:1px solid var(--rule);\n      padding:16px 0;}\n    .toc-wrap{max-height:0; overflow:hidden; transition:max-height .3s ease}\n    .toc-wrap.open{max-height:2400px}\n    .toc-toggle{display:flex !important}\n  }\n  .brand{font-family:"Spectral",serif; font-weight:700; font-size:1.05rem; color:var(--green);\n    letter-spacing:-.01em; margin-bottom:2px; display:flex; align-items:center; gap:8px;}\n  .brand .mark{width:26px;height:26px;border:1.5px solid var(--green);border-radius:5px;\n    display:grid;place-items:center;font-family:"IBM Plex Mono",monospace;font-size:.72rem;\n    font-weight:600;line-height:1;}\n  .brand .mark span{display:block}\n  .brand .mark .d{color:var(--green)} .brand .mark .c{color:var(--red)}\n  .side-sub{font-size:.72rem; color:var(--ink-faint); text-transform:none;\n    letter-spacing:.02em; margin:2px 0 18px 34px;}\n  .toc-toggle{display:none; width:100%; align-items:center; justify-content:space-between;\n    background:none;border:1px solid var(--rule); color:var(--ink); border-radius:8px;\n    padding:9px 12px; font-family:inherit; font-size:.85rem; font-weight:600; cursor:pointer;\n    margin-top:8px;}\n  nav a{display:block; font-size:.82rem; color:var(--ink-soft); text-decoration:none;\n    padding:5px 10px 5px 12px; border-left:2px solid transparent; line-height:1.35;\n    border-radius:0 6px 6px 0; transition:color .15s, background .15s, border-color .15s;}\n  nav a .num{font-family:"IBM Plex Mono",monospace; font-size:.72rem; color:var(--ink-faint);\n    margin-right:7px;}\n  nav a:hover{background:var(--paper-2); color:var(--ink)}\n  nav a.active{color:var(--green); border-left-color:var(--green); background:var(--paper-2);\n    font-weight:600;}\n  nav a.active .num{color:var(--green)}\n\n  /* main */\n  main{padding:0 0 90px; min-width:0}\n  .hero{padding:56px 0 30px; border-bottom:2px solid var(--rule-strong); margin-bottom:6px;\n    position:relative;}\n  .eyebrow{font-family:"IBM Plex Mono",monospace; font-size:.74rem; color:var(--green-bright);\n    letter-spacing:.04em; margin-bottom:14px;}\n  h1{font-family:"Spectral",serif; font-weight:800; font-size:clamp(2.1rem,5vw,3.1rem);\n    line-height:1.05; margin:.1em 0 .35em; letter-spacing:-.02em; color:var(--ink);}\n  .lede{font-size:1.06rem; color:var(--ink-soft); max-width:60ch; margin:0}\n  .hero-meta{display:flex; flex-wrap:wrap; gap:8px; margin-top:22px}\n  .chip{font-size:.76rem; font-weight:600; color:var(--green); background:var(--paper-2);\n    border:1px solid var(--green-line); padding:5px 11px; border-radius:20px;}\n  .chip.red{color:var(--red); border-color:var(--red-soft); background:transparent}\n\n  .toolbar{display:flex; gap:8px; flex-wrap:wrap; margin-top:22px}\n  .btn{font-family:inherit; font-size:.8rem; font-weight:600; cursor:pointer;\n    background:var(--card); color:var(--ink); border:1px solid var(--rule-strong);\n    padding:8px 13px; border-radius:8px; display:inline-flex; align-items:center; gap:6px;\n    transition:transform .1s, border-color .15s;}\n  .btn:hover{border-color:var(--green); color:var(--green)}\n  .btn:active{transform:translateY(1px)}\n\n  /* progress panel */\n  .prog{margin:26px 0 8px; background:var(--card); border:1px solid var(--rule);\n    border-radius:12px; padding:16px 18px; box-shadow:var(--shadow);}\n  .prog-top{display:flex; justify-content:space-between; align-items:baseline; gap:12px;\n    font-size:.85rem; color:var(--ink-soft);}\n  .prog-top b{font-family:"Spectral",serif; font-size:1.4rem; color:var(--green); font-weight:700}\n  .prog-track{height:8px; background:var(--paper-2); border-radius:6px; margin-top:10px;\n    overflow:hidden; border:1px solid var(--rule);}\n  .prog-fill{height:100%; width:0%; background:linear-gradient(90deg,var(--green),var(--green-bright));\n    transition:width .4s ease; border-radius:6px;}\n  .prog small{display:block; margin-top:9px; font-size:.76rem; color:var(--ink-faint)}\n\n  /* sections */\n  section{padding:38px 0 8px; scroll-margin-top:14px; border-bottom:1px solid var(--rule)}\n  section:last-of-type{border-bottom:none}\n  .sec-head{display:flex; align-items:flex-start; gap:14px; margin-bottom:6px}\n  .sec-no{font-family:"IBM Plex Mono",monospace; font-weight:600; font-size:.9rem;\n    color:var(--green); border:1.5px solid var(--green-line); border-radius:8px;\n    padding:6px 9px; line-height:1; margin-top:8px; flex:none; min-width:38px; text-align:center;}\n  h2{font-family:"Spectral",serif; font-weight:700; font-size:clamp(1.55rem,3.4vw,2.05rem);\n    line-height:1.15; margin:.15em 0 .1em; letter-spacing:-.015em; color:var(--ink);}\n  .revise{margin-left:auto; display:flex; align-items:center; gap:7px; font-size:.76rem;\n    color:var(--ink-faint); cursor:pointer; user-select:none; margin-top:10px; flex:none;\n    white-space:nowrap;}\n  .revise input{accent-color:var(--green); width:16px; height:16px; cursor:pointer}\n  h3{font-family:"Spectral",serif; font-weight:600; font-size:1.28rem; margin:1.5em 0 .3em;\n    color:var(--green); letter-spacing:-.01em;}\n  h4{font-size:1rem; font-weight:700; margin:1.3em 0 .2em; color:var(--ink)}\n  p{margin:.55em 0; max-width:var(--maxw)}\n  ul,ol{max-width:var(--maxw); padding-left:1.25em; margin:.5em 0}\n  li{margin:.32em 0}\n  li::marker{color:var(--green-bright)}\n  b,strong{font-weight:700; color:var(--ink)}\n  .term{font-weight:700; color:var(--green)}\n  em{color:var(--ink-soft)}\n  a.inline{color:var(--green); text-decoration:underline; text-decoration-color:var(--green-line)}\n\n  /* definition block */\n  .def{border-left:3px solid var(--green); background:var(--paper-2); padding:12px 16px;\n    border-radius:0 10px 10px 0; margin:1em 0; max-width:var(--maxw);}\n  .def .k{font-family:"IBM Plex Mono",monospace; font-size:.7rem; color:var(--green-bright);\n    letter-spacing:.03em; display:block; margin-bottom:3px;}\n\n  /* callouts */\n  .note{border:1px solid var(--rule-strong); border-radius:12px; padding:14px 18px 14px 16px;\n    margin:1.1em 0; max-width:var(--maxw); background:var(--card); box-shadow:var(--shadow);\n    border-left:4px solid var(--gold);}\n  .note.trap{border-left-color:var(--red)}\n  .note.mnem{border-left-color:var(--green-bright)}\n  .note .tag{font-family:"IBM Plex Mono",monospace; font-size:.7rem; font-weight:600;\n    letter-spacing:.03em; display:block; margin-bottom:4px; color:var(--gold);}\n  .note.trap .tag{color:var(--red)}\n  .note.mnem .tag{color:var(--green-bright)}\n  .note p{margin:.25em 0}\n\n  /* tables — ledger style */\n  .tbl-wrap{overflow-x:auto; margin:1.2em 0; border:1px solid var(--rule-strong);\n    border-radius:12px; box-shadow:var(--shadow); background:var(--card);}\n  table{border-collapse:collapse; width:100%; min-width:440px; font-size:.9rem}\n  caption{text-align:left; font-family:"Spectral",serif; font-weight:600; font-size:1.02rem;\n    padding:12px 16px 8px; color:var(--green);}\n  th,td{padding:9px 14px; text-align:left; border-bottom:1px solid var(--rule);\n    vertical-align:top;}\n  thead th{background:var(--paper-2); font-weight:700; color:var(--ink); font-size:.82rem;\n    border-bottom:2px solid var(--rule-strong);}\n  tbody tr:last-child td{border-bottom:none}\n  tbody tr:hover{background:var(--paper-2)}\n  td.num,th.num{font-family:"IBM Plex Mono",monospace; font-variant-numeric:tabular-nums;\n    text-align:right;}\n  .dr{color:var(--red); font-weight:600}\n  .cr{color:var(--green); font-weight:600}\n\n  /* T-account */\n  .taccount{max-width:440px; margin:1.2em 0; border:1.5px solid var(--rule-strong);\n    border-radius:10px; overflow:hidden; background:var(--card); box-shadow:var(--shadow);}\n  .taccount .ttitle{text-align:center; font-family:"Spectral",serif; font-weight:600;\n    padding:8px; border-bottom:1.5px solid var(--rule-strong); background:var(--paper-2);}\n  .tgrid{display:grid; grid-template-columns:1fr 1fr}\n  .tgrid > div{padding:10px 14px; min-height:70px}\n  .tgrid .left{border-right:1.5px solid var(--rule-strong)}\n  .tgrid .hd{font-family:"IBM Plex Mono",monospace; font-size:.74rem; font-weight:600;\n    margin-bottom:6px;}\n  .tgrid .left .hd{color:var(--red)} .tgrid .right .hd{color:var(--green)}\n  .tgrid .row{font-size:.85rem; display:flex; justify-content:space-between; gap:10px}\n  .tgrid .amt{font-family:"IBM Plex Mono",monospace; font-variant-numeric:tabular-nums}\n\n  /* formula strip */\n  .formula{font-family:"IBM Plex Mono",monospace; font-size:.95rem; background:var(--paper-2);\n    border:1px dashed var(--rule-strong); border-radius:10px; padding:12px 16px; margin:1em 0;\n    max-width:var(--maxw); color:var(--ink); overflow-x:auto; line-height:1.9;}\n  .formula .op{color:var(--green-bright); font-weight:600}\n\n  /* self test */\n  .qa{border:1px solid var(--rule); border-radius:12px; margin:.7em 0; background:var(--card);\n    max-width:var(--maxw); overflow:hidden;}\n  .qa summary{cursor:pointer; padding:13px 16px; font-weight:600; list-style:none;\n    display:flex; gap:10px; align-items:flex-start;}\n  .qa summary::-webkit-details-marker{display:none}\n  .qa summary::before{content:"Q"; font-family:"IBM Plex Mono",monospace; color:var(--green);\n    font-weight:700; flex:none; border:1.5px solid var(--green-line); border-radius:6px;\n    width:24px; height:24px; display:grid; place-items:center; font-size:.78rem;}\n  .qa[open] summary{border-bottom:1px solid var(--rule)}\n  .qa .ans{padding:12px 16px 14px 50px; color:var(--ink-soft); font-size:.94rem}\n  .qa .ans b{color:var(--green)}\n\n  .grid2{display:grid; grid-template-columns:1fr 1fr; gap:16px; max-width:var(--maxw)}\n  @media(max-width:620px){.grid2{grid-template-columns:1fr}}\n\n  footer{max-width:var(--maxw); margin-top:40px; padding-top:22px; border-top:2px solid var(--rule-strong);\n    font-size:.84rem; color:var(--ink-faint);}\n  footer b{color:var(--ink-soft)}\n\n  .backtop{position:fixed; right:20px; bottom:20px; z-index:40; width:44px; height:44px;\n    border-radius:50%; background:var(--green); color:#fff; border:none; cursor:pointer;\n    box-shadow:var(--shadow); font-size:1.2rem; opacity:0; pointer-events:none;\n    transition:opacity .25s; display:grid; place-items:center;}\n  .backtop.show{opacity:1; pointer-events:auto}\n\n  /* ---- primary button + PYQ modal ---- */\n  .btn-primary{background:var(--green); color:#fff; border-color:var(--green)}\n  .btn-primary:hover{background:var(--green-bright); color:#fff; border-color:var(--green-bright)}\n  .btn-count{font-family:"IBM Plex Mono",monospace; font-size:.68rem; background:rgba(255,255,255,.22);\n    padding:1px 6px; border-radius:10px; margin-left:2px;}\n\n  .modal-overlay{position:fixed; inset:0; z-index:100; background:rgba(8,16,12,.6);\n    -webkit-backdrop-filter:blur(3px); backdrop-filter:blur(3px);\n    display:none; opacity:0; transition:opacity .2s; padding:22px 14px;\n    padding-top:calc(22px + env(safe-area-inset-top,0px));\n    padding-bottom:calc(22px + env(safe-area-inset-bottom,0px));\n    overflow-y:auto;}\n  .modal-overlay.open{display:flex; opacity:1; align-items:flex-start; justify-content:center}\n  @media (prefers-reduced-motion:reduce){.modal-overlay{transition:none}}\n\n  .modal-card{background:var(--paper); width:100%; max-width:780px; border-radius:16px;\n    border:1px solid var(--rule-strong); box-shadow:0 30px 90px -30px rgba(0,0,0,.65);\n    margin:auto; display:flex; flex-direction:column; max-height:calc(100vh - 44px); overflow:hidden;}\n  .modal-head{padding:16px 20px 12px; border-bottom:1px solid var(--rule); background:var(--card); flex:none;}\n  .mh-row{display:flex; align-items:center; gap:12px}\n  .mh-row h3{margin:0; font-family:"Spectral",serif; color:var(--green); font-size:1.3rem; letter-spacing:-.01em}\n  .mh-row .sub{font-size:.74rem; color:var(--ink-faint); margin-top:2px}\n  .modal-close{margin-left:auto; background:none; border:1px solid var(--rule-strong);\n    border-radius:9px; width:36px; height:36px; cursor:pointer; color:var(--ink); font-size:1.15rem;\n    line-height:1; flex:none;}\n  .modal-close:hover{border-color:var(--red); color:var(--red)}\n  .scorebar{display:flex; gap:8px; align-items:center; margin-top:12px; flex-wrap:wrap}\n  .pill{font-size:.76rem; font-weight:600; padding:5px 11px; border-radius:20px;\n    background:var(--paper-2); border:1px solid var(--rule); color:var(--ink-soft);}\n  .pill b{color:var(--green)} .pill.wrongp b{color:var(--red)}\n  .filter{display:flex; gap:6px; flex-wrap:nowrap; overflow-x:auto; margin-top:12px;\n    padding-bottom:3px; scrollbar-width:thin}\n  .filter::-webkit-scrollbar{height:5px}\n  .filter::-webkit-scrollbar-thumb{background:var(--rule-strong); border-radius:3px}\n  .filter button{font-size:.73rem; padding:5px 11px; border-radius:16px; cursor:pointer; font-family:inherit;\n    border:1px solid var(--rule-strong); background:var(--card); color:var(--ink-soft); white-space:nowrap;}\n  .filter button:hover{border-color:var(--green)}\n  .filter button.active{background:var(--green); color:#fff; border-color:var(--green)}\n\n  .modal-body{padding:4px 20px 18px; overflow-y:auto; flex:1 1 auto; min-height:0}\n  .quiz-q{padding:18px 0; border-bottom:1px solid var(--rule)}\n  .quiz-q:last-child{border-bottom:none}\n  .quiz-q.hide{display:none}\n  .quiz-meta{display:flex; gap:7px; flex-wrap:wrap; margin-bottom:9px; align-items:center}\n  .qn-badge{font-family:"IBM Plex Mono",monospace; font-size:.72rem; font-weight:600; color:var(--green);\n    border:1.5px solid var(--green-line); border-radius:7px; padding:2px 7px;}\n  .qtag{font-family:"IBM Plex Mono",monospace; font-size:.65rem; font-weight:600; padding:3px 8px;\n    border-radius:12px; letter-spacing:.02em;}\n  .qtag.topic{color:var(--green); background:var(--paper-2); border:1px solid var(--green-line)}\n  .qtag.year{color:var(--gold); border:1px solid var(--gold)}\n  .quiz-qtext{font-weight:600; margin:0 0 11px; line-height:1.55; color:var(--ink)}\n  .quiz-data{font-size:.84rem; background:var(--paper-2); border:1px solid var(--rule);\n    border-radius:9px; padding:9px 13px; margin:0 0 12px; color:var(--ink-soft); overflow-x:auto; line-height:1.6}\n  .quiz-data b{color:var(--ink)}\n  .quiz-data table{border-collapse:collapse; width:auto; min-width:0; margin-top:6px; font-size:.82rem}\n  .quiz-data th,.quiz-data td{border:1px solid var(--rule-strong); padding:4px 9px; text-align:left}\n  .quiz-data th{background:var(--card); color:var(--ink)}\n  .quiz-opts{display:grid; gap:8px}\n  .quiz-opt{text-align:left; font-family:inherit; font-size:.92rem; padding:11px 14px; width:100%;\n    border:1.5px solid var(--rule-strong); border-radius:11px; background:var(--card); color:var(--ink);\n    cursor:pointer; display:flex; gap:11px; align-items:flex-start; line-height:1.45;\n    transition:border-color .15s, background .15s;}\n  .quiz-opt:hover:not(.locked){border-color:var(--green)}\n  .quiz-opt .lit{font-family:"IBM Plex Mono",monospace; font-weight:600; color:var(--green-bright); flex:none}\n  .quiz-opt.locked{cursor:default}\n  .quiz-opt.correct{border-color:var(--green); background:rgba(18,120,82,.14)}\n  .quiz-opt.correct .lit{color:var(--green)}\n  .quiz-opt.wrong{border-color:var(--red); background:rgba(158,43,37,.12)}\n  .quiz-opt.wrong .lit{color:var(--red)}\n  .quiz-opt .mk{margin-left:auto; font-weight:700; flex:none}\n  .quiz-explain{margin-top:11px; font-size:.87rem; color:var(--ink-soft); border-left:3px solid var(--green);\n    background:var(--paper-2); padding:9px 13px; border-radius:0 9px 9px 0; display:none}\n  .quiz-explain.show{display:block}\n  .quiz-explain .lead{font-family:"IBM Plex Mono",monospace; font-size:.68rem; font-weight:600;\n    color:var(--green); display:block; margin-bottom:3px; letter-spacing:.02em}\n  .quiz-explain.miss{border-left-color:var(--red)}\n  .quiz-explain.miss .lead{color:var(--red)}\n  .quiz-explain b{color:var(--ink)}\n  .empty{padding:40px 10px; text-align:center; color:var(--ink-faint); font-size:.9rem}\n\n  .modal-foot{padding:12px 20px; border-top:1px solid var(--rule); background:var(--card);\n    display:flex; gap:10px; justify-content:space-between; align-items:center; flex-wrap:wrap; flex:none;}\n  .modal-foot small{font-size:.75rem; color:var(--ink-faint)}\n  body.modal-open{overflow:hidden}\n\n  @media(max-width:560px){\n    .modal-card{border-radius:14px; max-height:calc(100vh - 28px)}\n    .mh-row h3{font-size:1.12rem}\n    .modal-head,.modal-body,.modal-foot{padding-left:15px; padding-right:15px}\n  }\n\n  /* ---- attempt-mode test flow ---- */\n  .attempt-bar{margin-top:12px}\n  .qcounter{font-size:.82rem; color:var(--ink-soft); display:flex; align-items:center; gap:10px}\n  .qcounter b{color:var(--green); font-family:"IBM Plex Mono",monospace}\n  .mini-progress{flex:1; height:6px; background:var(--paper-2); border:1px solid var(--rule);\n    border-radius:5px; overflow:hidden}\n  .mini-progress i{display:block; height:100%; width:0; border-radius:5px;\n    background:linear-gradient(90deg,var(--green),var(--green-bright)); transition:width .3s}\n  .navigator{display:flex; gap:6px; overflow-x:auto; padding:11px 0 3px; scrollbar-width:thin}\n  .navigator::-webkit-scrollbar{height:5px}\n  .navigator::-webkit-scrollbar-thumb{background:var(--rule-strong); border-radius:3px}\n  .nav-chip{flex:none; width:30px; height:30px; border-radius:8px; border:1.5px solid var(--rule-strong);\n    background:var(--card); color:var(--ink-soft); font-size:.76rem; font-family:"IBM Plex Mono",monospace;\n    cursor:pointer; display:grid; place-items:center; padding:0}\n  .nav-chip.answered{border-color:var(--green); color:var(--green); background:rgba(18,120,82,.10)}\n  .nav-chip.current{background:var(--green); color:#fff; border-color:var(--green)}\n  .nav-chip.correct{border-color:var(--green); color:var(--green); background:rgba(18,120,82,.16)}\n  .nav-chip.wrong{border-color:var(--red); color:var(--red); background:rgba(158,43,37,.14)}\n\n  .quiz-opt.selected{border-color:var(--green); background:rgba(18,120,82,.09)}\n  .quiz-opt.selected .lit{color:var(--green)}\n  .single .quiz-q{border-bottom:none; padding-top:8px}\n\n  .foot-nav{display:flex; gap:10px; align-items:center; width:100%; justify-content:space-between}\n  .foot-nav .grow{flex:1; text-align:center}\n  .foot-nav .btn{white-space:nowrap}\n\n  .result{padding:26px 6px 10px; text-align:center}\n  .result .big{font-family:"Spectral",serif; font-size:2.7rem; color:var(--green); font-weight:800; line-height:1}\n  .result .lbl{color:var(--ink-faint); font-size:.86rem; margin-top:5px}\n  .result .brk{display:flex; gap:10px; justify-content:center; margin-top:18px; flex-wrap:wrap}\n  .result .stat{background:var(--paper-2); border:1px solid var(--rule); border-radius:11px;\n    padding:11px 18px; min-width:92px}\n  .result .stat b{display:block; font-size:1.5rem; font-family:"Spectral",serif; line-height:1.1}\n  .result .stat.good b{color:var(--green)} .result .stat.bad b{color:var(--red)} .result .stat.skip b{color:var(--ink-faint)}\n  .result .stat span{font-size:.72rem; color:var(--ink-faint)}\n  .result .msg{margin-top:18px; font-size:.9rem; color:var(--ink-soft)}\n\n  @media print{\n    body::before,#scrollbar,aside,.toolbar,.backtop,.prog,.toc-toggle,.modal-overlay{display:none !important}\n    .wrap{display:block; max-width:none}\n    section{break-inside:avoid; border-bottom:1px solid #ccc}\n    .qa{break-inside:avoid} .qa .ans{display:block !important}\n    a{color:inherit; text-decoration:none}\n  }\n</style>\n</head>\n<body>\n<div id="scrollbar"></div>\n<div class="wrap">\n\n  <!-- SIDEBAR -->\n  <aside>\n    <div class="brand">\n      <span class="mark"><span class="d">Dr</span><span class="c">Cr</span></span>\n      APFC Accounting\n    </div>\n    <div class="side-sub">Complete concept &amp; revision note · 2026</div>\n    <button class="toc-toggle" id="tocToggle" aria-expanded="false">Contents <span>▾</span></button>\n    <div class="toc-wrap" id="tocWrap">\n      <nav id="toc"></nav>\n    </div>\n  </aside>\n\n  <!-- MAIN -->\n  <main>\n    <header class="hero">\n      <div class="eyebrow">UPSC · EPFO · Assistant Provident Fund Commissioner 2026</div>\n      <h1>Accounting</h1>\n      <p class="lede">The full backbone of the General Accounting portion — from first principles to final accounts — written to be understood once and revised many times before the exam.</p>\n      <div class="hero-meta">\n        <span class="chip">General Accounting Principles</span>\n        <span class="chip">Concept + Formula + MCQ traps</span>\n        <span class="chip red">Revision-first layout</span>\n      </div>\n      <div class="toolbar">\n        <button class="btn btn-primary" id="pyqBtn">✎ Practice PYQs <span class="btn-count" id="pyqCount">35</span></button>\n        <button class="btn" id="themeBtn">◑ Theme</button>\n        <button class="btn" id="printBtn">⎙ Print / Save PDF</button>\n        <button class="btn" id="resetBtn">↺ Reset progress</button>\n      </div>\n\n      <div class="prog">\n        <div class="prog-top"><span>Revision progress</span><span><b id="progPct">0%</b></span></div>\n        <div class="prog-track"><div class="prog-fill" id="progFill"></div></div>\n        <small id="progText">Tick “Mark revised” on each section as you finish it. Your progress is saved on this device.</small>\n      </div>\n    </header>\n\n    <!-- 1 -->\n    <section id="s1" data-title="Introduction to Accounting">\n      <div class="sec-head"><div class="sec-no">01</div><h2>Introduction to Accounting</h2></div>\n\n      <div class="def"><span class="k">DEFINITION</span>\n      <b>Accounting</b> is the art of <b>recording, classifying and summarising</b> in a significant manner, and in terms of money, transactions and events which are, in part at least, of a financial character, and <b>interpreting</b> the results thereof. <em>(American Institute of Certified Public Accountants — AICPA)</em></div>\n\n      <h3>Book-keeping vs Accounting vs Accountancy</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Basis</th><th>Book-keeping</th><th>Accounting</th><th>Accountancy</th></tr></thead>\n        <tbody>\n          <tr><td>Scope</td><td>Recording &amp; classifying</td><td>Recording → summarising → interpreting</td><td>Whole body of knowledge/principles</td></tr>\n          <tr><td>Stage</td><td>Primary / clerical</td><td>Analytical</td><td>Conceptual framework</td></tr>\n          <tr><td>Skill</td><td>Lower level</td><td>Higher, needs judgement</td><td>Highest</td></tr>\n          <tr><td>Relation</td><td>Begins the process</td><td>Begins where book-keeping ends</td><td>Governs both</td></tr>\n        </tbody>\n      </table></div>\n\n      <h3>Objectives &amp; functions</h3>\n      <ul>\n        <li>Maintain <b>systematic records</b> of financial transactions.</li>\n        <li>Ascertain <b>profit or loss</b> (via Trading and P&amp;L account).</li>\n        <li>Ascertain <b>financial position</b> (via Balance Sheet).</li>\n        <li>Provide information to <b>users</b> for decision-making.</li>\n        <li>Act as legal evidence and help meet statutory/tax obligations.</li>\n      </ul>\n\n      <h3>Branches of accounting</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Branch</th><th>Focus</th></tr></thead>\n        <tbody>\n          <tr><td><b>Financial accounting</b></td><td>Historical records; profit &amp; financial position for external users.</td></tr>\n          <tr><td><b>Cost accounting</b></td><td>Ascertaining and controlling cost of products/services.</td></tr>\n          <tr><td><b>Management accounting</b></td><td>Internal reports to help managers plan, decide and control.</td></tr>\n        </tbody>\n      </table></div>\n\n      <h3>Users of accounting information</h3>\n      <div class="grid2">\n        <div class="def"><span class="k">INTERNAL</span> Owners, management, employees.</div>\n        <div class="def"><span class="k">EXTERNAL</span> Investors, lenders/banks, creditors, government &amp; tax authorities, researchers, public.</div>\n      </div>\n\n      <h3>Basis of accounting</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Cash basis</th><th>Accrual (mercantile) basis</th></tr></thead>\n        <tbody>\n          <tr><td>Records only when cash is received/paid.</td><td>Records when income is <b>earned</b> / expense is <b>incurred</b>, regardless of cash.</td></tr>\n          <tr><td>Ignores outstanding &amp; prepaid items.</td><td>Considers outstanding, prepaid, accrued items.</td></tr>\n          <tr><td>Not recognised by Companies Act.</td><td>Legally required for companies; gives a true picture.</td></tr>\n        </tbody>\n      </table></div>\n\n      <div class="note mnem"><span class="tag">REMEMBER</span><p>Accounting <b>records only monetary</b> transactions — quality of management, staff morale, etc. are important but <b>not recorded</b> (money measurement concept).</p></div>\n    </section>\n\n    <!-- 2 -->\n    <section id="s2" data-title="Basic Accounting Terms">\n      <div class="sec-head"><div class="sec-no">02</div><h2>Basic Accounting Terms</h2></div>\n      <p>These recur in every chapter and in objective questions — fix the exact meanings.</p>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Term</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Capital</b></td><td>Amount invested by the owner; a liability of the business towards the owner.</td></tr>\n          <tr><td><b>Drawings</b></td><td>Cash/goods withdrawn by owner for personal use; reduces capital.</td></tr>\n          <tr><td><b>Assets</b></td><td>Resources owned that give future benefit — <em>fixed, current, tangible, intangible, fictitious</em>.</td></tr>\n          <tr><td><b>Liabilities</b></td><td>Amounts owed by the business — internal (capital) &amp; external (creditors, loans).</td></tr>\n          <tr><td><b>Debtor</b></td><td>Person who owes money <b>to</b> the business.</td></tr>\n          <tr><td><b>Creditor</b></td><td>Person to whom the business owes money.</td></tr>\n          <tr><td><b>Revenue / income</b></td><td>Inflow from sale of goods, services, interest, commission, etc.</td></tr>\n          <tr><td><b>Expense</b></td><td>Cost incurred to earn revenue (rent, salary, wages).</td></tr>\n          <tr><td><b>Expenditure</b></td><td>Spending of money — <em>capital</em> (long-term benefit) vs <em>revenue</em> (short-term).</td></tr>\n          <tr><td><b>Purchases / Sales</b></td><td>Goods bought / sold for resale (cash or credit).</td></tr>\n          <tr><td><b>Stock (Inventory)</b></td><td>Goods unsold — opening &amp; closing stock.</td></tr>\n          <tr><td><b>Goods</b></td><td>Items in which the business regularly deals.</td></tr>\n          <tr><td><b>Voucher</b></td><td>Documentary evidence of a transaction.</td></tr>\n        </tbody>\n      </table></div>\n      <div class="note trap"><span class="tag">MCQ TRAP</span><p><b>Fictitious assets</b> are <em>not real assets</em> — they are unwritten-off expenses/losses (e.g. preliminary expenses, discount on issue of shares). <b>Intangible assets</b> (goodwill, patents) <em>are</em> real and have value.</p></div>\n    </section>\n\n    <!-- 3 -->\n    <section id="s3" data-title="Accounting Principles (GAAP)">\n      <div class="sec-head"><div class="sec-no">03</div><h2>Accounting Principles — GAAP</h2></div>\n      <p><b>GAAP</b> = Generally Accepted Accounting Principles: the common rules that make statements uniform and comparable. They split into <b>concepts</b> (assumptions) and <b>conventions</b> (practices).</p>\n\n      <h3>Accounting concepts</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Concept</th><th>Core idea</th></tr></thead>\n        <tbody>\n          <tr><td><b>Business entity</b></td><td>Business is separate from its owner; owner\'s capital is a liability of the business.</td></tr>\n          <tr><td><b>Money measurement</b></td><td>Only transactions expressible in money are recorded.</td></tr>\n          <tr><td><b>Going concern</b></td><td>Business will continue for the foreseeable future; assets recorded at cost, not break-up value.</td></tr>\n          <tr><td><b>Accounting period</b></td><td>Life is split into fixed periods (usually 1 year) to measure results.</td></tr>\n          <tr><td><b>Cost concept</b></td><td>Assets recorded at acquisition (historical) cost.</td></tr>\n          <tr><td><b>Dual aspect</b></td><td>Every transaction has two effects — basis of double entry. <em>Assets = Liabilities + Capital.</em></td></tr>\n          <tr><td><b>Matching</b></td><td>Match expenses of a period with revenues of the same period to find true profit.</td></tr>\n          <tr><td><b>Realisation</b></td><td>Revenue is recognised when it is <b>earned/realised</b>, not when cash is received.</td></tr>\n          <tr><td><b>Accrual</b></td><td>Record income/expense when it arises, irrespective of cash flow.</td></tr>\n          <tr><td><b>Objectivity</b></td><td>Records must be based on verifiable evidence (vouchers).</td></tr>\n        </tbody>\n      </table></div>\n\n      <h3>Accounting conventions</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Convention</th><th>Core idea</th></tr></thead>\n        <tbody>\n          <tr><td><b>Consistency</b></td><td>Same methods followed year to year → comparability.</td></tr>\n          <tr><td><b>Conservatism (Prudence)</b></td><td>“Anticipate no profit, provide for all possible losses.” Closing stock at <em>cost or market, whichever is lower</em>.</td></tr>\n          <tr><td><b>Materiality</b></td><td>Record/disclose only items significant enough to affect decisions.</td></tr>\n          <tr><td><b>Full disclosure</b></td><td>All relevant information must be disclosed truthfully.</td></tr>\n        </tbody>\n      </table></div>\n\n      <div class="note mnem"><span class="tag">AS-1 · FUNDAMENTAL ASSUMPTIONS</span><p>Under Accounting Standard 1, three assumptions are presumed unless stated otherwise: <b>Going concern, Consistency, Accrual</b>. If followed, no disclosure needed; if <em>not</em> followed, disclosure is required.</p></div>\n      <div class="note trap"><span class="tag">MCQ TRAP</span><p>Valuing closing stock at “cost or market price, whichever is lower” is an application of <b>Conservatism / Prudence</b> — a very common one-liner question.</p></div>\n    </section>\n\n    <!-- 4 -->\n    <section id="s4" data-title="Accounting Equation">\n      <div class="sec-head"><div class="sec-no">04</div><h2>The Accounting Equation</h2></div>\n      <p>Flowing from the <b>dual aspect concept</b>, total assets always equal total claims against them.</p>\n      <div class="formula">Assets <span class="op">=</span> Liabilities <span class="op">+</span> Capital<br>\n      Capital <span class="op">=</span> Assets <span class="op">−</span> Liabilities<br>\n      Capital <span class="op">=</span> Opening Capital <span class="op">+</span> Profit <span class="op">+</span> Fresh Capital <span class="op">−</span> Drawings</div>\n      <h3>Effect of transactions (illustration)</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Transaction</th><th>Assets</th><th>Liabilities</th><th>Capital</th></tr></thead>\n        <tbody>\n          <tr><td>Started business with cash ₹1,00,000</td><td class="num">+1,00,000</td><td class="num">0</td><td class="num">+1,00,000</td></tr>\n          <tr><td>Bought goods on credit ₹20,000</td><td class="num">+20,000</td><td class="num">+20,000</td><td class="num">0</td></tr>\n          <tr><td>Paid creditor ₹5,000</td><td class="num">−5,000</td><td class="num">−5,000</td><td class="num">0</td></tr>\n          <tr><td>Owner withdrew ₹2,000</td><td class="num">−2,000</td><td class="num">0</td><td class="num">−2,000</td></tr>\n        </tbody>\n      </table></div>\n      <div class="note"><span class="tag">KEY</span><p>Whatever the transaction, the equation must <b>stay balanced</b>. If it doesn\'t, an error exists.</p></div>\n    </section>\n\n    <!-- 5 -->\n    <section id="s5" data-title="Double Entry & Golden Rules">\n      <div class="sec-head"><div class="sec-no">05</div><h2>Double Entry &amp; Golden Rules</h2></div>\n      <div class="def"><span class="k">DOUBLE ENTRY SYSTEM</span> Every transaction affects <b>two accounts</b> — one debited, one credited — with equal amounts. Total debits always equal total credits.</div>\n      <p><b>Advantages:</b> complete record, arithmetical accuracy checked via trial balance, easy to detect fraud/errors, reliable profit and position.</p>\n\n      <h3>Traditional (British) classification of accounts</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Type</th><th>Covers</th><th>Golden rule</th></tr></thead>\n        <tbody>\n          <tr><td><b>Personal</b></td><td>Persons, firms, institutions (Ram\'s A/c, Bank A/c, Capital A/c)</td><td><span class="dr">Dr</span> the receiver, <span class="cr">Cr</span> the giver</td></tr>\n          <tr><td><b>Real</b></td><td>Assets &amp; property (Cash, Machinery, Building)</td><td><span class="dr">Dr</span> what comes in, <span class="cr">Cr</span> what goes out</td></tr>\n          <tr><td><b>Nominal</b></td><td>Expenses, losses, incomes, gains (Rent, Salary, Interest received)</td><td><span class="dr">Dr</span> all expenses &amp; losses, <span class="cr">Cr</span> all incomes &amp; gains</td></tr>\n        </tbody>\n      </table></div>\n\n      <h3>Modern (American) approach — rules by nature of account</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Account</th><th>Increase</th><th>Decrease</th></tr></thead>\n        <tbody>\n          <tr><td>Assets</td><td class="dr">Debit</td><td class="cr">Credit</td></tr>\n          <tr><td>Expenses / Losses</td><td class="dr">Debit</td><td class="cr">Credit</td></tr>\n          <tr><td>Liabilities</td><td class="cr">Credit</td><td class="dr">Debit</td></tr>\n          <tr><td>Capital</td><td class="cr">Credit</td><td class="dr">Debit</td></tr>\n          <tr><td>Income / Gains</td><td class="cr">Credit</td><td class="dr">Debit</td></tr>\n        </tbody>\n      </table></div>\n      <div class="note mnem"><span class="tag">MNEMONIC</span><p><b>“DEAD CLIC”</b> → <b>D</b>ebit increases <b>E</b>xpenses, <b>A</b>ssets, <b>D</b>rawings · <b>C</b>redit increases <b>L</b>iabilities, <b>I</b>ncome, <b>C</b>apital.</p></div>\n    </section>\n\n    <!-- 6 -->\n    <section id="s6" data-title="Journal">\n      <div class="sec-head"><div class="sec-no">06</div><h2>Journal — the Book of Original Entry</h2></div>\n      <p>The journal records transactions <b>chronologically</b> before posting to the ledger. The process is called <b>journalising</b>.</p>\n      <div class="tbl-wrap"><table>\n        <caption>Journal format</caption>\n        <thead><tr><th>Date</th><th>Particulars</th><th>L.F.</th><th class="num">Dr (₹)</th><th class="num">Cr (₹)</th></tr></thead>\n        <tbody>\n          <tr><td>Apr 1</td><td>Cash A/c … <span class="dr">Dr</span><br>&nbsp;&nbsp;&nbsp;To Capital A/c<br><em>(Being business started with cash)</em></td><td>—</td><td class="num">1,00,000</td><td class="num">—</td></tr>\n          <tr><td></td><td></td><td></td><td class="num">—</td><td class="num">1,00,000</td></tr>\n        </tbody>\n      </table></div>\n      <ul>\n        <li><b>Narration</b> — the brief explanation in brackets under each entry.</li>\n        <li><b>Compound entry</b> — one entry involving more than two accounts.</li>\n        <li><b>L.F.</b> (Ledger Folio) — page number where the entry is posted in the ledger.</li>\n      </ul>\n    </section>\n\n    <!-- 7 -->\n    <section id="s7" data-title="Ledger">\n      <div class="sec-head"><div class="sec-no">07</div><h2>Ledger — the Book of Final Entry</h2></div>\n      <p>The ledger is the principal book that contains all <b>accounts</b>. Transferring entries from journal to ledger is <b>posting</b>. A <b>“T-account”</b> has a debit (left) and credit (right) side.</p>\n      <div class="taccount">\n        <div class="ttitle">Cash Account</div>\n        <div class="tgrid">\n          <div class="left"><div class="hd">Dr</div>\n            <div class="row"><span>To Capital A/c</span><span class="amt">1,00,000</span></div>\n          </div>\n          <div class="right"><div class="hd">Cr</div>\n            <div class="row"><span>By Purchases A/c</span><span class="amt">20,000</span></div>\n            <div class="row"><span>By Balance c/d</span><span class="amt">80,000</span></div>\n          </div>\n        </div>\n      </div>\n      <p><b>Balancing:</b> the difference between the two sides is the closing balance (<em>balance c/d</em>), carried to the next period as <em>balance b/d</em>. Assets/expenses normally have a <b>debit</b> balance; liabilities/capital/income a <b>credit</b> balance.</p>\n    </section>\n\n    <!-- 8 -->\n    <section id="s8" data-title="Trial Balance">\n      <div class="sec-head"><div class="sec-no">08</div><h2>Trial Balance</h2></div>\n      <div class="def"><span class="k">DEFINITION</span> A <b>statement</b> (not an account) listing debit and credit balances of all ledger accounts on a given date, prepared to test the <b>arithmetical accuracy</b> of the books.</div>\n      <p><b>Objectives:</b> check arithmetic accuracy · basis for final accounts · summary of all accounts · helps locate errors.</p>\n\n      <h3>Errors that a trial balance can &amp; cannot detect</h3>\n      <div class="grid2">\n        <div class="note trap"><span class="tag">NOT DISCLOSED (agrees despite error)</span>\n          <p>Errors of <b>omission</b> (complete) · errors of <b>principle</b> · errors of <b>commission</b> that are compensating · recording <b>wrong amount</b> in both accounts · posting to <b>wrong account of the same class</b>.</p></div>\n        <div class="note"><span class="tag">DISCLOSED (trial balance disagrees)</span>\n          <p>Posting to <b>wrong side</b> · posting <b>wrong amount</b> to one account · <b>omitting</b> to post one side · <b>wrong casting</b> (totalling) · errors in carrying forward.</p></div>\n      </div>\n      <div class="note trap"><span class="tag">MCQ TRAP</span><p>A trial balance that <b>tallies is not a proof of complete accuracy</b> — errors of principle and complete omission still leave it balanced.</p></div>\n    </section>\n\n    <!-- 9 -->\n    <section id="s9" data-title="Subsidiary Books & Cash Book">\n      <div class="sec-head"><div class="sec-no">09</div><h2>Subsidiary Books &amp; Cash Book</h2></div>\n      <p>When transactions are many, the journal is split into <b>special/subsidiary books</b> for speed and division of labour.</p>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Subsidiary book</th><th>Records</th></tr></thead>\n        <tbody>\n          <tr><td>Purchases book</td><td>Credit purchases of goods only.</td></tr>\n          <tr><td>Sales book</td><td>Credit sales of goods only.</td></tr>\n          <tr><td>Purchase returns (returns outward)</td><td>Goods returned to suppliers.</td></tr>\n          <tr><td>Sales returns (returns inward)</td><td>Goods returned by customers.</td></tr>\n          <tr><td>Bills receivable / payable book</td><td>Bills of exchange received / accepted.</td></tr>\n          <tr><td>Cash book</td><td>All cash &amp; bank transactions.</td></tr>\n          <tr><td>Journal proper</td><td>Entries not fitting any special book (opening, closing, adjustments).</td></tr>\n        </tbody>\n      </table></div>\n\n      <h3>Types of cash book</h3>\n      <ul>\n        <li><b>Single column</b> — cash only.</li>\n        <li><b>Double column</b> — cash + bank (or cash + discount).</li>\n        <li><b>Triple column</b> — cash, bank and discount columns.</li>\n        <li><b>Petty cash book</b> — small routine payments, usually on the <b>imprest system</b> (a fixed float is reimbursed to the original amount each period).</li>\n      </ul>\n      <div class="note mnem"><span class="tag">DUAL NATURE</span><p>The cash book is <b>both a subsidiary book and a ledger account</b> — cash/bank accounts are not separately opened in the ledger.</p></div>\n      <div class="note trap"><span class="tag">MCQ TRAP</span><p><b>Contra entry</b> = a transaction affecting both cash and bank columns (e.g. cash deposited into bank), marked with the letter <b>“C”</b>; it is not posted to the ledger again.</p></div>\n    </section>\n\n    <!-- 10 -->\n    <section id="s10" data-title="Bank Reconciliation Statement">\n      <div class="sec-head"><div class="sec-no">10</div><h2>Bank Reconciliation Statement (BRS)</h2></div>\n      <div class="def"><span class="k">DEFINITION</span> A statement reconciling the balance shown by the firm\'s <b>cash book (bank column)</b> with the balance shown by the <b>pass book / bank statement</b> on a particular date.</div>\n      <h3>Common causes of difference</h3>\n      <ul>\n        <li>Cheques <b>issued but not yet presented</b> for payment.</li>\n        <li>Cheques <b>deposited but not yet cleared/credited</b>.</li>\n        <li>Bank charges, interest debited by bank not entered in cash book.</li>\n        <li>Interest/dividends collected by bank directly.</li>\n        <li>Direct deposits by customers; standing-order payments by bank.</li>\n        <li>Errors in the cash book or the pass book.</li>\n      </ul>\n      <div class="note"><span class="tag">APPROACH</span><p>Start from one balance, then add/subtract each item according to how it affects <em>that</em> book, to arrive at the other balance. Remember: an overdraft is a <b>credit balance in the cash book</b> and a <b>debit balance in the pass book</b>.</p></div>\n    </section>\n\n    <!-- 11 -->\n    <section id="s11" data-title="Depreciation, Provisions & Reserves">\n      <div class="sec-head"><div class="sec-no">11</div><h2>Depreciation, Provisions &amp; Reserves</h2></div>\n      <div class="def"><span class="k">DEPRECIATION</span> The <b>permanent, continuous and gradual</b> fall in the book value of a fixed asset due to use, wear &amp; tear, obsolescence or efflux of time. It is a <b>non-cash</b> expense charged against profit.</div>\n      <p><b>Causes:</b> wear and tear, passage of time, obsolescence, depletion, accidents.</p>\n\n      <h3>Straight-line vs Written-down-value method</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Basis</th><th>Straight Line (SLM / Fixed Instalment)</th><th>Written Down Value (WDV / Diminishing)</th></tr></thead>\n        <tbody>\n          <tr><td>Charged on</td><td>Original cost</td><td>Book value (reducing balance)</td></tr>\n          <tr><td>Amount each year</td><td>Equal every year</td><td>Decreases every year</td></tr>\n          <tr><td>Book value</td><td>Can become zero</td><td>Never becomes exactly zero</td></tr>\n          <tr><td>Suitable for</td><td>Assets with uniform use (furniture, patents)</td><td>Assets needing higher early write-off (machinery, vehicles)</td></tr>\n          <tr><td>Recognised by</td><td>—</td><td>Income Tax Act (mainly)</td></tr>\n        </tbody>\n      </table></div>\n      <div class="formula">SLM p.a. <span class="op">=</span> (Cost <span class="op">−</span> Scrap value) <span class="op">÷</span> Useful life</div>\n\n      <h3>Provision vs Reserve</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Provision</th><th>Reserve</th></tr></thead>\n        <tbody>\n          <tr><td>For a <b>known liability</b> of uncertain amount (e.g. provision for doubtful debts).</td><td>Appropriation of <b>profit</b> to strengthen the business.</td></tr>\n          <tr><td>Charge <b>against</b> profit (compulsory).</td><td>Appropriation <b>of</b> profit (after profit is found).</td></tr>\n          <tr><td>Created even if there is a loss.</td><td>Created only if there are profits.</td></tr>\n          <tr><td>Not available for dividend.</td><td>Can be used for dividend (revenue reserve).</td></tr>\n        </tbody>\n      </table></div>\n      <div class="note trap"><span class="tag">MCQ TRAP</span><p><b>Reserve</b> vs <b>Provision</b>: provision reduces profit and is a <em>charge</em>; reserve is created <em>from</em> profit. Also distinguish <b>revenue reserve</b> (distributable) from <b>capital reserve</b> (not for dividend).</p></div>\n    </section>\n\n    <!-- 12 -->\n    <section id="s12" data-title="Rectification of Errors">\n      <div class="sec-head"><div class="sec-no">12</div><h2>Rectification of Errors</h2></div>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Error type</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Error of omission</b></td><td>Transaction fully or partly not recorded.</td></tr>\n          <tr><td><b>Error of commission</b></td><td>Wrong amount, wrong posting, wrong casting, wrong balancing.</td></tr>\n          <tr><td><b>Error of principle</b></td><td>Ignoring accounting principles — e.g. treating capital expenditure as revenue.</td></tr>\n          <tr><td><b>Compensating error</b></td><td>Two or more errors that cancel each other\'s effect.</td></tr>\n        </tbody>\n      </table></div>\n      <div class="note"><span class="tag">SUSPENSE ACCOUNT</span><p>When a trial balance does not agree and the difference cannot be located before final accounts, it is temporarily placed in a <b>suspense account</b>. As one-sided errors are rectified, the suspense account is cleared; when it shows nil, all such errors are corrected.</p></div>\n    </section>\n\n    <!-- 13 -->\n    <section id="s13" data-title="Final Accounts">\n      <div class="sec-head"><div class="sec-no">13</div><h2>Final Accounts</h2></div>\n      <p>Prepared at year-end to know profit/loss and financial position. Order: <b>Trading A/c → Profit &amp; Loss A/c → Balance Sheet</b>.</p>\n\n      <h3>1 · Trading Account</h3>\n      <p>Finds <b>Gross Profit</b> (or gross loss) from buying and selling.</p>\n      <div class="formula">Gross Profit <span class="op">=</span> Net Sales <span class="op">−</span> Cost of Goods Sold<br>\n      COGS <span class="op">=</span> Opening Stock <span class="op">+</span> Net Purchases <span class="op">+</span> Direct Expenses <span class="op">−</span> Closing Stock</div>\n      <p><em>Direct expenses:</em> wages, carriage inward, freight, factory rent, power &amp; fuel.</p>\n\n      <h3>2 · Profit &amp; Loss Account</h3>\n      <p>Starts with gross profit; deducts <b>indirect expenses</b> (office, selling, financial) and adds other incomes to give <b>Net Profit</b>.</p>\n      <div class="formula">Net Profit <span class="op">=</span> Gross Profit <span class="op">+</span> Other Incomes <span class="op">−</span> Indirect Expenses</div>\n\n      <h3>3 · Balance Sheet</h3>\n      <p>A <b>statement</b> (not an account) of assets and liabilities showing financial position on a date. It always balances (dual aspect). <b>Marshalling</b> = the order of arranging items — by <em>liquidity</em> or by <em>permanence</em>.</p>\n\n      <h3>Common adjustments</h3>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Adjustment</th><th>Treatment</th></tr></thead>\n        <tbody>\n          <tr><td>Closing stock</td><td>Credit Trading A/c; show as current asset in B/S.</td></tr>\n          <tr><td>Outstanding expense</td><td>Add to expense (P&amp;L); show as liability.</td></tr>\n          <tr><td>Prepaid expense</td><td>Deduct from expense; show as asset.</td></tr>\n          <tr><td>Accrued income</td><td>Add to income; show as asset.</td></tr>\n          <tr><td>Income received in advance</td><td>Deduct from income; show as liability.</td></tr>\n          <tr><td>Depreciation</td><td>Debit P&amp;L; deduct from asset in B/S.</td></tr>\n          <tr><td>Bad debts / provision for doubtful debts</td><td>Debit P&amp;L; deduct from debtors.</td></tr>\n        </tbody>\n      </table></div>\n      <div class="note mnem"><span class="tag">GOLDEN CHECK</span><p>Every adjustment given <b>outside</b> the trial balance affects <b>two places</b> — one in Trading/P&amp;L, one in the Balance Sheet.</p></div>\n    </section>\n\n    <!-- 14 -->\n    <section id="s14" data-title="Bills of Exchange">\n      <div class="sec-head"><div class="sec-no">14</div><h2>Bills of Exchange (Overview)</h2></div>\n      <div class="def"><span class="k">DEFINITION (NI ACT 1881)</span> An instrument in writing containing an <b>unconditional order</b>, signed by the maker, directing a certain person to pay a certain sum of money only to, or to the order of, a certain person or the bearer.</div>\n      <ul>\n        <li><b>Drawer</b> — maker (creditor) who draws the bill.</li>\n        <li><b>Drawee</b> — the person directed to pay (debtor); becomes <b>acceptor</b> after accepting.</li>\n        <li><b>Payee</b> — the person to receive payment.</li>\n        <li><b>Days of grace</b> — 3 extra days added to compute the due date.</li>\n        <li><b>Discounting</b> — getting a bill encashed from a bank before due date at a discount.</li>\n        <li><b>Endorsement / dishonour / noting</b> — transfer, non-payment, and its official record by a notary.</li>\n      </ul>\n    </section>\n\n    <!-- 15 -->\n    <section id="s15" data-title="Accounting Standards, Ind AS & IFRS">\n      <div class="sec-head"><div class="sec-no">15</div><h2>Accounting Standards, Ind AS &amp; IFRS</h2></div>\n      <ul>\n        <li><b>Accounting Standards (AS)</b> — written policy documents issued by the <b>ICAI</b> (Institute of Chartered Accountants of India) to bring uniformity.</li>\n        <li><b>Ind AS</b> — Indian Accounting Standards converged with IFRS, notified by the Ministry of Corporate Affairs; applicable to specified companies in phases.</li>\n        <li><b>IFRS</b> — International Financial Reporting Standards issued by the <b>IASB</b>, aimed at global comparability.</li>\n        <li><b>Objectives of standards:</b> uniformity, comparability, reliability, reduced accounting alternatives.</li>\n      </ul>\n      <div class="note trap"><span class="tag">EXAM POINTER</span><p><b>AS</b> in India are issued by <b>ICAI</b>; <b>IFRS</b> by the <b>IASB</b>. Ind AS are “converged with” (not identical to) IFRS.</p></div>\n    </section>\n\n    <!-- 16 -->\n    <section id="s16" data-title="Ratio Analysis (Essentials)">\n      <div class="sec-head"><div class="sec-no">16</div><h2>Ratio Analysis — Essentials</h2></div>\n      <p>Tools to interpret financial statements. Group and remember the standard ratios.</p>\n      <div class="tbl-wrap"><table>\n        <thead><tr><th>Type</th><th>Ratio</th><th>Formula</th></tr></thead>\n        <tbody>\n          <tr><td rowspan="2"><b>Liquidity</b></td><td>Current ratio</td><td>Current Assets ÷ Current Liabilities <em>(ideal 2:1)</em></td></tr>\n          <tr><td>Quick / Acid-test</td><td>(Current Assets − Stock − Prepaid) ÷ Current Liabilities <em>(ideal 1:1)</em></td></tr>\n          <tr><td rowspan="2"><b>Solvency</b></td><td>Debt–Equity</td><td>Long-term Debt ÷ Shareholders\' Funds</td></tr>\n          <tr><td>Proprietary</td><td>Shareholders\' Funds ÷ Total Assets</td></tr>\n          <tr><td rowspan="2"><b>Profitability</b></td><td>Gross profit ratio</td><td>(Gross Profit ÷ Net Sales) × 100</td></tr>\n          <tr><td>Net profit ratio</td><td>(Net Profit ÷ Net Sales) × 100</td></tr>\n          <tr><td rowspan="2"><b>Activity / Turnover</b></td><td>Stock turnover</td><td>COGS ÷ Average Stock</td></tr>\n          <tr><td>Debtors turnover</td><td>Net Credit Sales ÷ Average Debtors</td></tr>\n        </tbody>\n      </table></div>\n    </section>\n\n    <!-- 17 -->\n    <section id="s17" data-title="Cost & Management Accounting">\n      <div class="sec-head"><div class="sec-no">17</div><h2>Cost &amp; Management Accounting (Basics)</h2></div>\n      <ul>\n        <li><b>Elements of cost:</b> Material, Labour, Expenses → each <em>direct</em> or <em>indirect</em>. Indirect items together form <b>overheads</b>.</li>\n        <li><b>Prime cost</b> = Direct Material + Direct Labour + Direct Expenses.</li>\n        <li><b>Cost of production</b> = Prime cost + Factory (works) overhead + Office overhead.</li>\n        <li><b>Behaviour:</b> fixed, variable and semi-variable costs.</li>\n        <li><b>Marginal costing &amp; break-even:</b> <em>Contribution = Sales − Variable cost</em>; <em>BEP (units) = Fixed cost ÷ Contribution per unit</em>.</li>\n        <li><b>Management accounting</b> uses this data (plus budgets, standards) purely for <b>internal decisions</b>; it has no fixed statutory format.</li>\n      </ul>\n      <div class="formula">Contribution <span class="op">=</span> Sales <span class="op">−</span> Variable Cost<br>\n      BEP (units) <span class="op">=</span> Fixed Cost <span class="op">÷</span> Contribution per unit<br>\n      P/V ratio <span class="op">=</span> (Contribution <span class="op">÷</span> Sales) <span class="op">×</span> 100</div>\n    </section>\n\n    <!-- 18 SELF TEST -->\n    <section id="s18" data-title="Quick Self-Test">\n      <div class="sec-head"><div class="sec-no">18</div><h2>Quick Self-Test</h2></div>\n      <p>Answer in your head, then reveal. Great for the final days before the exam.</p>\n\n      <details class="qa"><summary>Which concept treats the owner and the business as separate?</summary>\n        <div class="ans"><b>Business entity concept.</b> Owner\'s capital is therefore a liability of the business.</div></details>\n      <details class="qa"><summary>Valuing stock at “cost or market price, whichever is lower” follows which convention?</summary>\n        <div class="ans"><b>Conservatism / Prudence.</b></div></details>\n      <details class="qa"><summary>Golden rule for a nominal account?</summary>\n        <div class="ans"><b>Debit all expenses &amp; losses, Credit all incomes &amp; gains.</b></div></details>\n      <details class="qa"><summary>Name two errors a trial balance cannot disclose.</summary>\n        <div class="ans">Any two of: <b>error of complete omission, error of principle, compensating error, wrong amount recorded in both accounts, posting to wrong account of the same class.</b></div></details>\n      <details class="qa"><summary>Under which method does depreciation stay equal every year?</summary>\n        <div class="ans"><b>Straight-line (fixed instalment) method</b>, charged on original cost.</div></details>\n      <details class="qa"><summary>Difference between a provision and a reserve in one line?</summary>\n        <div class="ans">A <b>provision is a charge against profit</b> for a known liability; a <b>reserve is an appropriation of profit</b>.</div></details>\n      <details class="qa"><summary>Formula for Gross Profit?</summary>\n        <div class="ans"><b>Gross Profit = Net Sales − Cost of Goods Sold</b>, where COGS = Opening Stock + Net Purchases + Direct Expenses − Closing Stock.</div></details>\n      <details class="qa"><summary>Who issues Accounting Standards in India, and who issues IFRS?</summary>\n        <div class="ans">Accounting Standards → <b>ICAI</b>; IFRS → <b>IASB</b>.</div></details>\n      <details class="qa"><summary>Ideal current ratio and quick ratio?</summary>\n        <div class="ans"><b>Current ratio 2:1</b>, <b>Quick ratio 1:1.</b></div></details>\n      <details class="qa"><summary>What is a contra entry?</summary>\n        <div class="ans">A transaction affecting <b>both cash and bank columns</b> of the cash book (e.g. cash deposited into bank), marked “C” and not re-posted to the ledger.</div></details>\n    </section>\n\n    <footer>\n      <p><b>How to use this note:</b> First pass — read every section for understanding and tick “Mark revised.” Later passes — skim the tables, formula strips and MCQ-trap boxes, then close the page and attempt Section 18 from memory.</p>\n      <p style="margin-top:10px">Prepared as a concept + revision aid for the <b>UPSC APFC (EPFO) 2026</b> General Accounting portion. Always cross-check numeric formats and the latest official syllabus/notification before the exam.</p>\n    </footer>\n  </main>\n</div>\n\n<button class="backtop" id="backtop" aria-label="Back to top">↑</button>\n\n<script>\n(function(){\n  "use strict";\n  var LS_THEME="apfc_acc_theme", LS_PROG="apfc_acc_progress_v1";\n  var root=document.documentElement;\n\n  /* ---------- safe storage ---------- */\n  function get(k){try{return localStorage.getItem(k);}catch(e){return null;}}\n  function set(k,v){try{localStorage.setItem(k,v);}catch(e){}}\n  function del(k){try{localStorage.removeItem(k);}catch(e){}}\n\n  /* ---------- theme ---------- */\n  var saved=get(LS_THEME);\n  if(saved){root.setAttribute("data-theme",saved);}\n  document.getElementById("themeBtn").addEventListener("click",function(){\n    var cur=root.getAttribute("data-theme")||"light";\n    var next=cur==="light"?"dark":"light";\n    root.setAttribute("data-theme",next); set(LS_THEME,next);\n  });\n\n  /* ---------- build TOC + revise checkboxes ---------- */\n  var secs=Array.prototype.slice.call(document.querySelectorAll("section[data-title]"));\n  var toc=document.getElementById("toc");\n  var progress={};\n  try{progress=JSON.parse(get(LS_PROG)||"{}")||{};}catch(e){progress={};}\n\n  secs.forEach(function(sec,i){\n    var id=sec.id, title=sec.getAttribute("data-title");\n    var n=String(i+1).padStart(2,"0");\n    // toc link\n    var a=document.createElement("a");\n    a.href="#"+id; a.dataset.target=id;\n    a.innerHTML=\'<span class="num">\'+n+\'</span>\'+title;\n    toc.appendChild(a);\n    // revise checkbox in section head\n    var head=sec.querySelector(".sec-head");\n    var lbl=document.createElement("label");\n    lbl.className="revise";\n    var cb=document.createElement("input");\n    cb.type="checkbox"; cb.checked=!!progress[id];\n    lbl.appendChild(cb);\n    lbl.appendChild(document.createTextNode("Mark revised"));\n    head.appendChild(lbl);\n    cb.addEventListener("change",function(){\n      progress[id]=cb.checked; set(LS_PROG,JSON.stringify(progress)); updateProgress();\n    });\n  });\n\n  var links=Array.prototype.slice.call(toc.querySelectorAll("a"));\n\n  /* ---------- progress meter ---------- */\n  var fill=document.getElementById("progFill"),\n      pct=document.getElementById("progPct"),\n      ptext=document.getElementById("progText");\n  function updateProgress(){\n    var done=secs.filter(function(s){return progress[s.id];}).length;\n    var total=secs.length;\n    var p=Math.round(done/total*100);\n    fill.style.width=p+"%"; pct.textContent=p+"%";\n    ptext.textContent = done===0\n      ? "Tick “Mark revised” on each section as you finish it. Your progress is saved on this device."\n      : done+" of "+total+" sections revised"+(p===100?" — full coverage. Now attempt Section 18 blind.":".");\n  }\n  updateProgress();\n\n  /* ---------- reset ---------- */\n  document.getElementById("resetBtn").addEventListener("click",function(){\n    if(!confirm("Clear your revision progress on this device?"))return;\n    progress={}; del(LS_PROG);\n    document.querySelectorAll(".revise input").forEach(function(c){c.checked=false;});\n    updateProgress();\n  });\n\n  /* ---------- print ---------- */\n  document.getElementById("printBtn").addEventListener("click",function(){window.print();});\n\n  /* ---------- scrollbar + active section + backtop ---------- */\n  var sb=document.getElementById("scrollbar"), backtop=document.getElementById("backtop");\n  function onScroll(){\n    var st=window.scrollY||document.documentElement.scrollTop;\n    var h=document.documentElement.scrollHeight-window.innerHeight;\n    sb.style.width=(h>0?(st/h*100):0)+"%";\n    backtop.classList.toggle("show", st>500);\n  }\n  window.addEventListener("scroll",onScroll,{passive:true}); onScroll();\n  backtop.addEventListener("click",function(){window.scrollTo({top:0,behavior:"smooth"});});\n\n  /* keep the active sidebar link visible WITHOUT ever moving the page window.\n     (Calling scrollIntoView on a link inside the sticky sidebar could nudge the\n      whole page during a smooth scroll and land you on the wrong section.) */\n  var sidebar=document.querySelector("aside");\n  function keepLinkVisible(l){\n    if(!sidebar||!l)return;\n    var lr=l.getBoundingClientRect(), sr=sidebar.getBoundingClientRect();\n    if(lr.top<sr.top) sidebar.scrollTop-=(sr.top-lr.top)+8;\n    else if(lr.bottom>sr.bottom) sidebar.scrollTop+=(lr.bottom-sr.bottom)+8;\n  }\n\n  /* active link via IntersectionObserver */\n  if("IntersectionObserver" in window){\n    var byId={}; links.forEach(function(l){byId[l.dataset.target]=l;});\n    var obs=new IntersectionObserver(function(entries){\n      entries.forEach(function(en){\n        if(en.isIntersecting){\n          links.forEach(function(l){l.classList.remove("active");});\n          var l=byId[en.target.id]; if(l){l.classList.add("active"); keepLinkVisible(l);}\n        }\n      });\n    },{rootMargin:"-20% 0px -70% 0px",threshold:0});\n    secs.forEach(function(s){obs.observe(s);});\n  }\n\n  /* ---------- mobile TOC toggle ---------- */\n  var tg=document.getElementById("tocToggle"), tw=document.getElementById("tocWrap");\n  tg.addEventListener("click",function(){\n    var open=tw.classList.toggle("open");\n    tg.setAttribute("aria-expanded",open?"true":"false");\n    tg.querySelector("span").textContent=open?"▴":"▾";\n  });\n\n  /* Clicking a TOC link scrolls to the EXACT section, deterministically.\n     - Never touch the URL hash (a #id jump reloads a srcdoc iframe / trips SPA routers).\n     - On mobile, collapse the TOC INSTANTLY (no animation) BEFORE measuring, so the\n       reflow can\'t shift the target out from under us — that was the off-by-one. */\n  function isMobileTOC(){return window.matchMedia&&window.matchMedia("(max-width:940px)").matches;}\n  function scrollToSection(target){\n    var top=target.getBoundingClientRect().top+(window.pageYOffset||document.documentElement.scrollTop||0)-12;\n    window.scrollTo({top:top,behavior:"smooth"});\n  }\n  links.forEach(function(l){l.addEventListener("click",function(e){\n    e.preventDefault();\n    var target=document.getElementById(l.dataset.target);\n    if(!target)return;\n    if(isMobileTOC()){\n      var prevT=tw.style.transition;\n      tw.style.transition="none";            // collapse without animating\n      tw.classList.remove("open");\n      tg.setAttribute("aria-expanded","false");\n      var sp=tg.querySelector("span"); if(sp)sp.textContent="▾";\n      void tw.offsetHeight;                  // force reflow so layout is final\n      scrollToSection(target);\n      requestAnimationFrame(function(){ tw.style.transition=prevT; });\n    } else {\n      scrollToSection(target);\n    }\n  });});\n})();\n</script>\n\n<!-- ===== PYQ PRACTICE MODAL ===== -->\n<div class="modal-overlay" id="pyqOverlay" role="dialog" aria-modal="true" aria-labelledby="pyqTitle">\n  <div class="modal-card">\n    <div class="modal-head">\n      <div class="mh-row">\n        <div>\n          <h3 id="pyqTitle">Accountancy PYQs</h3>\n          <div class="sub">Attempt one at a time — pick an answer, move on, then submit</div>\n        </div>\n        <button class="modal-close" id="pyqClose" aria-label="Close practice">✕</button>\n      </div>\n      <div class="filter" id="pyqFilter"></div>\n      <div class="attempt-bar">\n        <div class="qcounter">\n          <span>Question <b id="qNow">1</b> / <span id="qTotal">0</span></span>\n          <span class="mini-progress"><i id="miniFill"></i></span>\n          <span id="answeredNote" style="font-size:.75rem;color:var(--ink-faint);white-space:nowrap"></span>\n        </div>\n        <div class="navigator" id="navigator" aria-label="Question navigator"></div>\n      </div>\n    </div>\n    <div class="modal-body" id="pyqBody"></div>\n    <div class="modal-foot" id="pyqFoot"></div>\n  </div>\n</div>\n\n<script>\n(function(){\n  "use strict";\n  var LS="apfc_acc_pyq_v2";\n\n  /* ---- Question bank: verified from the uploaded Topic-wise PYQ (Economy section) ---- */\n  var INV = \'<b>Perpetual inventory record</b>\'\n    + \'<table><thead><tr><th>Date</th><th>Particulars</th><th>Units</th><th>Rate/unit (₹)</th></tr></thead><tbody>\'\n    + \'<tr><td>Jan 1</td><td>Inventory in hand</td><td>200</td><td>7</td></tr>\'\n    + \'<tr><td>Jan 6</td><td>Issued for sale</td><td>100</td><td>&ndash;</td></tr>\'\n    + \'<tr><td>Jan 8</td><td>Purchases</td><td>1100</td><td>8</td></tr>\'\n    + \'<tr><td>Jan 9</td><td>Issued for sale</td><td>200</td><td>&ndash;</td></tr>\'\n    + \'<tr><td>Jan 25</td><td>Purchases</td><td>300</td><td>9</td></tr>\'\n    + \'</tbody></table>\';\n\n  var Q=[\n    {t:"Concepts & Standards",y:"APFC 2023",q:"A provision created against fluctuation in the value of investments is based on the convention of:",o:["Conservatism","Full disclosure","Materiality","Consistency"],a:0,e:"Providing for a possible fall in value — anticipating losses but not gains — is the essence of the <b>conservatism (prudence)</b> convention."},\n    {t:"Concepts & Standards",y:"APFC 2023",q:"According to Accounting Standard-1, which of the following are the fundamental accounting assumptions?",o:["Going Concern, Consistency, Accrual","Going Concern, Money Measurement, Conservatism","Going Concern, Consistency, Conservatism","Going Concern, Accounting Period, Accrual"],a:0,e:"AS-1 recognises three fundamental assumptions: <b>Going Concern, Consistency and Accrual</b>. If followed no disclosure is needed; if not, disclosure is required."},\n    {t:"Concepts & Standards",y:"APFC 2023",q:"In a business firm, assets are valued on the basis of their intrinsic value rather than realizable value. This accounting is based on:",o:["Money measurement concept","Matching concept","Going concern assumption","Consistency principle"],a:2,e:"Because the firm is assumed to continue rather than be sold off, assets are carried at cost/intrinsic value, not break-up value — the <b>going concern assumption</b>."},\n    {t:"Concepts & Standards",y:"APFC 2023",q:"Which of the following is NOT a major consideration in the selection and application of accounting policies?",o:["Prudence","Consistency","Substance over form","Materiality"],a:1,e:"The three primary considerations for selecting accounting policies are <b>Prudence, Substance over Form and Materiality</b>. <b>Consistency</b> is a fundamental assumption, not a selection consideration."},\n    {t:"Concepts & Standards",y:"APFC 2023",q:"Which one of the following is included in the \'Cost of Inventory\' according to Accounting Standard-2 (Inventory Valuation)?",o:["Administrative overheads that do not contribute to bringing the inventories to their present location and condition","Storage costs which are necessary in the production process prior to a further production stage","Selling and distribution costs","Duties and taxes on purchases that are subsequently recoverable from the tax authorities"],a:1,e:"AS-2 <b>excludes</b> non-contributing admin overheads, selling/distribution costs and recoverable taxes. Storage costs that are <b>necessary before a further production stage</b> are included in cost."},\n    {t:"Concepts & Standards",y:"APFC 2015/16",q:"In case of gold, revenue is recognized in the accounting period in which the gold is:",o:["delivered","sold","mined","identified to be mined"],a:2,e:"Gold (like other precious metals with assured realisability) is an exception to the realisation rule — revenue is recognised when it is <b>mined/produced</b>."},\n    {t:"Concepts & Standards",y:"APFC 2015/16",q:"As per the traditional approach, the expense to be matched with revenue is based on:",o:["original cost","opportunity cost","replacement cost","cash cost"],a:0,e:"Traditional accounting matches revenue with expenses measured at their <b>original (historical) cost</b>."},\n    {t:"Concepts & Standards",y:"APFC 2015/16",q:"In the context of accounting, the term IFRS stands for:",o:["International Financial Reporting Standards","Indian Financial Reporting Standards","Indian Financial Reporting System","International Financial Reporting System"],a:0,e:"<b>IFRS = International Financial Reporting Standards</b>, issued by the IASB for global comparability."},\n    {t:"Concepts & Standards",y:"EO/AO 2023",q:"The practice of appending notes regarding contingent liability in the accounting statements is pursuant to:",o:["Convention of consistency","Money measurement concept","Convention of conservatism","Convention of full disclosure"],a:3,e:"Disclosing contingent liabilities as notes, so users get complete information, reflects the <b>convention of full disclosure</b>."},\n\n    {t:"Account Types",y:"APFC 2023",q:"Goodwill Account is a/an:",o:["Personal Account","Real Account","Nominal Account","Expense Account"],a:1,e:"Goodwill is an <b>intangible asset</b>; accounts of assets/property are <b>real accounts</b>."},\n    {t:"Account Types",y:"EO/AO 2023",q:"\'Outstanding rent\' may be classified as a/an:",o:["Natural personal account","Representative personal account","Real account","Nominal account"],a:1,e:"Outstanding rent represents the persons to whom the rent is due, so it is a <b>representative personal account</b>."},\n    {t:"Account Types",y:"APFC 2015/16",q:"Income and Expenditure Account is a:",o:["Real Account","Personal Account","Nominal Account","Capital Account"],a:2,e:"Like a Profit &amp; Loss Account, it deals with incomes and expenses — a <b>nominal account</b>."},\n    {t:"Account Types",y:"APFC 2015/16",q:"Branch Account under the debtors system is a:",o:["Real account","Personal Account","Nominal account","Liability account"],a:2,e:"Under the debtors system the Branch Account is prepared to find the branch profit/loss, so it is <b>nominal</b> in nature."},\n\n    {t:"Capital vs Revenue",y:"APFC 2023",q:"The insurance claim received on account of machinery damaged completely by fire is a:",o:["capital receipt","revenue receipt","capital expenditure","revenue expenditure"],a:0,e:"A claim for a lost <b>fixed asset</b> is a <b>capital receipt</b> — it replaces a capital item, not routine income."},\n    {t:"Capital vs Revenue",y:"APFC 2023",q:"Which one of the following is NOT a capital expenditure?",o:["₹5,000 spent to remove a worn-out part of a machine","Expenses on a foreign tour for purchasing a new machine","Freight and insurance of the machinery purchased","Amount spent on repairing a secondhand machine before it is put to use"],a:0,e:"Merely removing a worn-out part is a <b>repair (revenue expense)</b>. The others are acquisition/installation costs and are capitalised."},\n    {t:"Capital vs Revenue",y:"EO/AO 2023",q:"Overhauling expenses of ₹25,000 for the engine of a motor car to get better fuel efficiency is:",o:["Deferred revenue expenditure","Revenue receipt","Capital expenditure","Revenue expenditure"],a:2,e:"Because it <b>increases the earning capacity/efficiency</b> of the asset, the overhaul is <b>capital expenditure</b>, not a routine repair."},\n    {t:"Capital vs Revenue",y:"APFC 2015/16",q:"Preliminary expenses are examples of:",o:["capital expenditure","capital gain","deferred revenue expenditure","revenue expenditure/expense"],a:2,e:"Preliminary (formation) expenses give benefit over several years and are written off gradually — <b>deferred revenue expenditure</b>."},\n    {t:"Capital vs Revenue",y:"APFC 2015/16",q:"Depreciation of fixed assets is an example of:",o:["deferred revenue expenditure","capital expenditure","capital gain","revenue expenditure/expense"],a:3,e:"Depreciation is a periodic charge against profit — a <b>revenue expenditure/expense</b>."},\n\n    {t:"Errors & Trial Balance",y:"APFC 2023",q:"Which one of the following is NOT an error of commission?",o:["Overcasting of the sales book","Credit sales to Ramesh ₹5,000 credited to his account","Wrong balancing of the machinery account","Cash sales not recorded in the cash book"],a:3,e:"Wrong casting, wrong posting and wrong balancing are errors of commission. <b>Completely failing to record</b> the cash sales is an <b>error of omission</b>."},\n    {t:"Errors & Trial Balance",y:"EO/AO 2023",q:"A credit purchase of machinery recorded in the Purchase Book instead of the Journal Proper is an example of:",o:["Compensating errors","Errors of commission","Errors of principle","Errors of omission"],a:2,e:"The Purchase Book is only for goods. Recording a <b>fixed asset</b> there confuses capital with revenue — an <b>error of principle</b>."},\n\n    {t:"Depreciation & Reserves",y:"APFC 2023",q:"Which one of the following statements is correct?",o:["Capital reserves are normally created out of free or distributable profits","Dividend equalization reserve is an example of general reserve","General reserve can be used only for some specific purposes","\'Provision\' is a charge against profit"],a:3,e:"A <b>provision is a charge against profit</b> (created even in a loss). Capital reserves arise from capital profits, a general reserve is for unspecified purposes, and a dividend-equalization reserve is a specific reserve."},\n    {t:"Depreciation & Reserves",y:"EO/AO 2023",q:"Which one of the following statements is NOT correct?",o:["Depreciation is a non-cash expense","Depreciation is the process of valuation of assets","The main cause of depreciation is wear and tear caused by usage","Depreciation must be charged so as to ascertain the true profit or loss"],a:1,e:"Depreciation is the <b>allocation of the cost</b> of a fixed asset over its life, <b>not a valuation</b> of the asset. The other three statements are correct."},\n\n    {t:"Final Accounts (Numericals)",y:"EO/AO 2023",d:"<b>Trial Balance (as on 31.03.2022) — extract</b><br>Trade receivables: ₹2,50,000 · Provision for discount to debtors: ₹14,000 · Discount to debtors: ₹4,000<br>Additional discount allowed to debtors during the year: ₹20,000. The firm maintains a provision for discount to debtors equal to <b>10% of trade receivables\' balances</b>.",q:"Total amount to be charged to the Profit &amp; Loss Account (for the year ending 31.03.2022) for discount allowed and provision for discount created will be:",o:["₹25,000","₹13,000","₹9,000","₹33,000"],a:3,e:"Discount actually allowed = ₹4,000 + ₹20,000 = ₹24,000. New provision = 10% of (₹2,50,000 − ₹20,000) = ₹23,000. Charge to P&amp;L = ₹24,000 + (₹23,000 − ₹14,000 old provision) = <b>₹33,000</b>."},\n    {t:"Final Accounts (Numericals)",y:"EO/AO 2023",d:INV,q:"The value of inventory on 31 January under the perpetual inventory system using the First-In-First-Out (FIFO) method is:",o:["₹6,700","₹8,700","₹10,700","₹12,000"],a:2,e:"Under FIFO the earliest units are issued first. After both issues the balance is 1,000 units @ ₹8 and 300 units @ ₹9 = ₹8,000 + ₹2,700 = <b>₹10,700</b>."},\n    {t:"Final Accounts (Numericals)",y:"APFC 2023",d:INV,q:"The value of inventory on 31 January under the perpetual inventory system using the Last-In-First-Out (LIFO) method is:",o:["₹6,600","₹8,600","₹10,600","₹12,000"],a:2,e:"Under perpetual LIFO the latest units are issued first. Jan 6 issue takes 100 @ ₹7; Jan 9 issue takes 200 @ ₹8. Closing = 100@₹7 + 900@₹8 + 300@₹9 = ₹700 + ₹7,200 + ₹2,700 = <b>₹10,600</b>."},\n    {t:"Final Accounts (Numericals)",y:"EO/AO 2023",d:"<b>Club — year ending 31.03.2022</b><br>Subscription outstanding on 31.03.2021: ₹16,000 · on 31.03.2022: ₹18,000<br>Subscription received in advance on 31.03.2021: ₹12,000 · on 31.03.2022: ₹11,000<br>70 members, each paying an annual subscription of ₹1,000.",q:"Total subscription received during the year 2021-22 will be:",o:["₹67,000","₹71,000","₹69,000","₹77,000"],a:0,e:"Income = 70 × ₹1,000 = ₹70,000. Cash received = ₹70,000 + opening outstanding ₹16,000 − closing outstanding ₹18,000 − opening advance ₹12,000 + closing advance ₹11,000 = <b>₹67,000</b>."},\n    {t:"Final Accounts (Numericals)",y:"APFC 2015/16",d:"Rate of gross profit: <b>25% on cost of goods sold</b> · Sales: <b>₹20,00,000</b>",q:"The amount of gross profit is:",o:["₹5,00,000","₹6,25,000","₹3,75,000","₹4,00,000"],a:3,e:"GP is 25% on cost, so Sales = 125% of cost → Cost = ₹20,00,000 ÷ 1.25 = ₹16,00,000. Gross profit = ₹20,00,000 − ₹16,00,000 = <b>₹4,00,000</b>."},\n\n    {t:"Consignment, JV & NPO",y:"APFC 2015/16",q:"The abnormal loss on consignment is credited to:",o:["Profit and loss account","Consignee\'s account","Consignment account","Income and expenditure account"],a:2,e:"Abnormal loss is removed from the Consignment Account by <b>crediting the Consignment Account</b> (and debiting the Abnormal Loss / P&amp;L Account)."},\n    {t:"Consignment, JV & NPO",y:"APFC 2015/16",q:"When goods are purchased for the joint venture, the amount is debited to:",o:["Purchase Account","Joint venture account","Venture\'s capital account","Profit and loss account"],a:1,e:"All joint-venture transactions run through the <b>Joint Venture Account</b>, which is debited when goods are purchased for the venture."},\n    {t:"Consignment, JV & NPO",y:"APFC 2015/16",q:"Legacies are generally:",o:["Capitalized and taken to the balance sheet","Treated as income","Treated as expenditure","Capitalized and taken to a suspense account"],a:0,e:"A legacy (amount received under a will) is a <b>capital receipt</b> for a non-profit organisation — capitalised and shown in the balance sheet (added to the capital fund)."},\n\n    {t:"Company & Partnership",y:"APFC 2015/16",q:"Under which Schedule of the Companies Act, 2013 are the formats of financial statements prescribed?",o:["Schedule I","Schedule II","Schedule III","Schedule IV"],a:2,e:"<b>Schedule III</b> prescribes the format of the balance sheet and the statement of profit &amp; loss. (Schedule II deals with depreciation/useful life of assets.)"},\n    {t:"Company & Partnership",y:"APFC 2015/16",q:"In the absence of any provision in the partnership agreement, profits and losses are shared by the partners:",o:["in the ratio of the capital of partners","equally","in the ratio of loans given by them to the firm","in the ratio of the initial capital introduced by the partners"],a:1,e:"Under the Indian Partnership Act, 1932, if the deed is silent, partners share profits and losses <b>equally</b>."},\n\n    {t:"Audit",y:"APFC 2023",q:"Which one of the following aspects is NOT covered in audit?",o:["Examination of the system of accounting and internal control","Preparation of the books of accounts","Reporting to the appropriate person/body","Verification of the authenticity and validity of transactions"],a:1,e:"<b>Preparation of the books of accounts</b> is an accounting (not auditing) function. Audit examines, verifies and reports — it does not create the records."},\n    {t:"Audit",y:"APFC 2023",q:"Which of the following sets the scope, timing and direction of the audit, and guides the development of the more detailed audit plan?",o:["Audit program","Overall audit strategy","Completion memorandum","Audit plan"],a:1,e:"The <b>overall audit strategy</b> sets the scope, timing and direction of the audit and guides the development of the detailed audit plan (SA-300)."},\n    {t:"Audit",y:"EO/AO 2023",q:"Reporting on fraud is to be made by an auditor to the Central Government when the sums involved in the fraud:",o:["exceed ₹20 lakh","exceed ₹50 lakh","exceed ₹75 lakh","are ₹1 crore or above"],a:3,e:"Under Section 143(12) of the Companies Act, 2013 (with the audit rules), fraud involving <b>₹1 crore or above</b> must be reported to the Central Government."}\n  ];\n\n  var LIT=["A","B","C","D"];\n\n  /* ---- state: chosen answers + submitted flag, saved on device ---- */\n  var st={ans:{},submitted:false};\n  try{var _s=JSON.parse(localStorage.getItem(LS)||"{}"); if(_s&&typeof _s==="object"){st.ans=_s.ans||{}; st.submitted=!!_s.submitted;}}catch(e){}\n  function save(){try{localStorage.setItem(LS,JSON.stringify(st));}catch(e){}}\n\n  var overlay=document.getElementById("pyqOverlay"),\n      body=document.getElementById("pyqBody"),\n      foot=document.getElementById("pyqFoot"),\n      filterWrap=document.getElementById("pyqFilter"),\n      nav=document.getElementById("navigator");\n\n  var curFilter="All", active=[], cur=0, mode=st.submitted?"review":"attempt";\n  document.getElementById("pyqCount").textContent=Q.length;\n\n  /* topic filter chips */\n  var topics=["All"]; Q.forEach(function(q){if(topics.indexOf(q.t)<0)topics.push(q.t);});\n  topics.forEach(function(t){\n    var b=document.createElement("button");\n    b.textContent=(t==="All"?"All ("+Q.length+")":t);\n    if(t==="All")b.classList.add("active");\n    b.addEventListener("click",function(){\n      curFilter=t;\n      filterWrap.querySelectorAll("button").forEach(function(x){x.classList.remove("active");});\n      b.classList.add("active");\n      buildActive(); cur=(mode==="review"?-1:0); render();\n    });\n    filterWrap.appendChild(b);\n  });\n\n  function buildActive(){ active=[]; Q.forEach(function(q,i){ if(curFilter==="All"||q.t===curFilter) active.push(i); }); }\n  function answeredCount(){ var n=0; active.forEach(function(gi){ if(st.ans[gi]!=null)n++; }); return n; }\n  function scoreCount(){ var c=0; active.forEach(function(gi){ if(st.ans[gi]===Q[gi].a)c++; }); return c; }\n  function btn(label,fn){ var b=document.createElement("button"); b.className="btn"; b.innerHTML=label; b.addEventListener("click",fn); return b; }\n\n  function render(){\n    document.getElementById("qTotal").textContent=active.length;\n    if(mode==="review" && cur===-1){ renderResult(); return; }\n    renderQuestion(); renderNav(); renderFoot();\n  }\n\n  function renderQuestion(){\n    var gi=active[cur], q=Q[gi], chosen=st.ans[gi];\n    document.getElementById("qNow").textContent=cur+1;\n    document.getElementById("miniFill").style.width=((cur+1)/active.length*100)+"%";\n    document.getElementById("answeredNote").textContent = mode==="review" ? (scoreCount()+" correct") : (answeredCount()+" answered");\n\n    var meta=\'<div class="quiz-meta"><span class="qn-badge">Q\'+(gi+1)+\'</span><span class="qtag topic">\'+q.t+\'</span><span class="qtag year">\'+q.y+\'</span></div>\';\n    var data=q.d?(\'<div class="quiz-data">\'+q.d+\'</div>\'):\'\';\n    var qtext=\'<p class="quiz-qtext">\'+q.q+\'</p>\';\n    var opts=\'<div class="quiz-opts">\';\n    q.o.forEach(function(opt,j){\n      var cls="quiz-opt", mk="";\n      if(mode==="attempt"){ if(chosen===j)cls+=" selected"; }\n      else{\n        cls+=" locked";\n        if(j===q.a){cls+=" correct"; mk=\'<span class="mk" style="color:var(--green)">\\u2713</span>\';}\n        else if(j===chosen){cls+=" wrong"; mk=\'<span class="mk" style="color:var(--red)">\\u2717</span>\';}\n      }\n      opts+=\'<button class="\'+cls+\'" data-opt="\'+j+\'"\'+(mode==="review"?\' disabled\':\'\')+\'><span class="lit">\'+LIT[j]+\'</span><span class="txt">\'+opt+\'</span>\'+mk+\'</button>\';\n    });\n    opts+=\'</div>\';\n\n    var exp="";\n    if(mode==="review"){\n      var miss=(chosen!==q.a);\n      var lead = (chosen==null) ? "NOT ATTEMPTED \\u2014 CORRECT ANSWER" : (miss?"NOT QUITE \\u2014 HERE\'S WHY":"CORRECT \\u2014 EXPLANATION");\n      exp=\'<div class="quiz-explain show\'+(miss?\' miss\':\'\')+\'"><span class="lead">\'+lead+\'</span>\'+q.e+\'</div>\';\n    }\n\n    body.className="modal-body single";\n    body.innerHTML=\'<div class="quiz-q">\'+meta+data+qtext+opts+exp+\'</div>\';\n    body.scrollTop=0;\n\n    if(mode==="attempt"){\n      body.querySelectorAll(".quiz-opt").forEach(function(b){\n        b.addEventListener("click",function(){\n          st.ans[gi]=parseInt(b.dataset.opt,10); save();\n          renderQuestion(); renderNav(); renderFoot();\n        });\n      });\n    }\n  }\n\n  function renderNav(){\n    nav.innerHTML="";\n    active.forEach(function(gi,idx){\n      var c=document.createElement("button"); c.className="nav-chip"; c.textContent=idx+1;\n      if(mode==="review"){ if(st.ans[gi]===Q[gi].a)c.classList.add("correct"); else if(st.ans[gi]!=null)c.classList.add("wrong"); }\n      else if(st.ans[gi]!=null)c.classList.add("answered");\n      if(idx===cur)c.classList.add("current");\n      c.addEventListener("click",function(){ cur=idx; render(); });\n      nav.appendChild(c);\n    });\n    var cn=nav.querySelector(".current"); if(cn&&cn.scrollIntoView)cn.scrollIntoView({inline:"center",block:"nearest"});\n  }\n\n  function renderFoot(){\n    foot.innerHTML="";\n    var wrap=document.createElement("div"); wrap.className="foot-nav";\n    var prev=btn("\\u25C0 Prev",function(){ if(cur>0){cur--;render();} }); prev.disabled=(cur===0);\n    var next=btn("Next \\u25B6",function(){ if(cur<active.length-1){cur++;render();} }); next.disabled=(cur===active.length-1);\n    var mid=document.createElement("div"); mid.className="grow";\n    if(mode==="attempt"){\n      var sub=btn("Submit ("+answeredCount()+"/"+active.length+")",submitTest); sub.className="btn btn-primary";\n      mid.appendChild(sub);\n    }else{\n      var sc=document.createElement("span"); sc.style.cssText="font-weight:600;font-size:.9rem";\n      sc.innerHTML=\'Score <b style="color:var(--green)">\'+scoreCount()+\'</b> / \'+active.length;\n      mid.appendChild(sc);\n    }\n    wrap.appendChild(prev); wrap.appendChild(mid); wrap.appendChild(next);\n    foot.appendChild(wrap);\n    if(mode==="review"){\n      var row2=document.createElement("div"); row2.style.cssText="display:flex;gap:10px;justify-content:center;margin-top:10px;width:100%";\n      row2.appendChild(btn("\\u25A4 Summary",function(){cur=-1;render();}));\n      row2.appendChild(btn("\\u21BA Retake",retake));\n      foot.appendChild(row2);\n    }\n  }\n\n  function renderResult(){\n    var total=active.length, cor=scoreCount(), att=answeredCount(), wrong=att-cor, skip=total-att;\n    var pct=total?Math.round(cor/total*100):0;\n    var verdict = pct>=80?"Strong \\u2014 exam-ready on these.":pct>=60?"Solid, but revise the misses.":pct>=40?"Keep drilling these topics.":"Revisit the note, then retry.";\n    document.getElementById("qNow").textContent="\\u2014";\n    document.getElementById("miniFill").style.width="100%";\n    document.getElementById("answeredNote").textContent=cor+" correct";\n    body.className="modal-body";\n    body.innerHTML=\'<div class="result"><div class="big">\'+pct+\'%</div>\'\n      +\'<div class="lbl">\'+cor+\' of \'+total+\' correct</div>\'\n      +\'<div class="brk">\'\n      +\'<div class="stat good"><b>\'+cor+\'</b><span>Correct</span></div>\'\n      +\'<div class="stat bad"><b>\'+wrong+\'</b><span>Wrong</span></div>\'\n      +\'<div class="stat skip"><b>\'+skip+\'</b><span>Skipped</span></div></div>\'\n      +\'<div class="msg">\'+verdict+\'</div></div>\';\n    body.scrollTop=0;\n    nav.innerHTML="";\n    active.forEach(function(gi,idx){\n      var c=document.createElement("button"); c.className="nav-chip"; c.textContent=idx+1;\n      if(st.ans[gi]===Q[gi].a)c.classList.add("correct"); else if(st.ans[gi]!=null)c.classList.add("wrong");\n      c.addEventListener("click",function(){cur=idx;render();});\n      nav.appendChild(c);\n    });\n    foot.innerHTML="";\n    var wrap=document.createElement("div"); wrap.className="foot-nav";\n    wrap.appendChild(btn("\\u21BA Retake",retake));\n    var g=document.createElement("div"); g.className="grow"; wrap.appendChild(g);\n    var rev=btn("Review answers \\u25B6",function(){cur=0;render();}); rev.className="btn btn-primary";\n    wrap.appendChild(rev);\n    foot.appendChild(wrap);\n  }\n\n  function submitTest(){\n    var un=active.length-answeredCount();\n    var msg = un>0 ? ("You still have "+un+" unanswered question(s). Submit anyway?") : "Submit and see your results?";\n    if(!confirm(msg))return;\n    st.submitted=true; save(); mode="review"; cur=-1; render();\n  }\n  function retake(){\n    if(!confirm("Clear your answers for this set and retake?"))return;\n    active.forEach(function(gi){ delete st.ans[gi]; });\n    st.submitted=false; save(); mode="attempt"; cur=0; render();\n  }\n\n  buildActive();\n  if(mode==="review") cur=-1;\n\n  /* open / close */\n  var lastFocus=null;\n  function openM(){ lastFocus=document.activeElement; buildActive(); if(mode==="review")cur=-1; render(); overlay.classList.add("open"); document.body.classList.add("modal-open"); document.getElementById("pyqClose").focus(); }\n  function closeM(){ overlay.classList.remove("open"); document.body.classList.remove("modal-open"); if(lastFocus&&lastFocus.focus)lastFocus.focus(); }\n  document.getElementById("pyqBtn").addEventListener("click",openM);\n  document.getElementById("pyqClose").addEventListener("click",closeM);\n  overlay.addEventListener("click",function(e){ if(e.target===overlay)closeM(); });\n  document.addEventListener("keydown",function(e){\n    if(!overlay.classList.contains("open"))return;\n    if(e.key==="Escape"){closeM();return;}\n    if(cur===-1)return;\n    if(e.key==="ArrowRight"&&cur<active.length-1){cur++;render();}\n    else if(e.key==="ArrowLeft"&&cur>0){cur--;render();}\n  });\n\n  render();\n})();\n</script>\n</body>\n</html>\n';

export default function AccountingNote({
  className,
  style,
  title = "Accounting revision note",
  ...rest
}) {
  return (
    <iframe
      title={title}
      srcDoc={html}
      className={className}
      style={{
        width: "100%",
        height: "100%",
        border: "none",
        background: "#f4f5fb",
        ...style,
      }}
      {...rest}
    />
  );
}
